function m(t){return!t||t<=0?null:9.81*t*t/8}function h(t){return!t||t<=0?null:9.81*t/2}const f={minContactSec:.08,maxContactSec:.8,minFlightSec:.1,maxFlightSec:2};function x(t,r){const n=Number(t),o=Number(r);if(!n||n<=0||!o||o<=0)return null;const e=f;if(o<e.minContactSec||o>e.maxContactSec)return{error:"contact_out_of_range",message:`접지 시간이 비현실적입니다(${e.minContactSec}~${e.maxContactSec}초 범위). 단위가 초(s)가 맞는지 확인하세요.`};if(n<e.minFlightSec||n>e.maxFlightSec)return{error:"flight_out_of_range",message:`체공 시간이 비현실적입니다(${e.minFlightSec}~${e.maxFlightSec}초 범위). 단위가 초(s)가 맞는지 확인하세요.`};const c=m(n),u=h(n),i=a=>Math.round(a*1e3)/1e3,l=a=>Math.round(a*100)/100;return{height:i(c),heightCm:Math.round(c*1e3)/10,rsi:l(n/o),rsiHeight:l(c/o),takeoffVelocity:l(u)}}const s=[{min:1.3,max:1/0,label:"스피드·파워",color:"blue"},{min:1,max:1.3,label:"근파워",color:"green"},{min:.75,max:1,label:"근력·파워",color:"yellow"},{min:.5,max:.75,label:"근비대·근력",color:"orange"},{min:0,max:.5,label:"최대근력",color:"red"}];function g(t){return s.find(r=>t>=r.min&&t<r.max)||null}function b(t,r){const n=Number(t),o=Number(r);if(!n||n<=0||!o||o<=0)return null;const e=n/o;return{meanVelocity:(c=>Math.round(c*100)/100)(e),zone:g(e)}}function S(t,r){const n=Number(t);if(!n||n<=0)return null;const o=m(n),e=Math.round(o*1e3)/10,c=h(n),u=a=>Math.round(a*100)/100;let i=null;const l=Number(r);return l&&l>0&&(i=Math.round(60.7*e+45.3*l-2055)),{heightCm:e,takeoffVelocity:u(c),peakPower:i}}export{x as b,S as d,s as h,b as x};
